\mathrm{df\text{-}prime\text{-}maximal\text{-}radical\text{-}ideal}\vdash\;\begin{aligned}
\mathsf{Prime}(\mathcal R,I)&\leftrightarrow\mathsf{Ideal}(\mathcal R,I)\land\forall a,b\in R\;(a\cdot_Rb\in I\to(a\in I\lor b\in I)),\\
\mathsf{MaxIdeal}(\mathcal R,I)&\leftrightarrow\mathsf{Ideal}(\mathcal R,I)\land\forall a\in R\;(a\notin I\to\exists b\in R\;a\cdot_Rb-_R1_R\in I),\\
\mathsf{RadIdeal}(\mathcal R,I)&\leftrightarrow\mathsf{Ideal}(\mathcal R,I)\land\forall a\in R\forall n>0\forall b\in R\;[(\mathsf{Pow}(\mathcal R,a,n,b)\land b\in I)\to a\in I].
\end{aligned}
